int mlx4_register_vlan(struct mlx4_dev *dev, u8 port, u16 vlan, int *index)
{
        struct mlx4_vlan_table *table;
        int i;
        int err = -EINVAL;

        if (!dev || port > MLX4_MAX_PORTS)
                return -EINVAL;

        table = &dev->port[port - 1].vlan_table;

        mutex_lock(&table->mutex);

        for (i = 0; i < table->size; ++i) {
                if (table->vlans[i] == vlan) {
                        table->ref_count[i]++;
                        *index = i;
                        err = 0;
                        goto out;
                }
        }

        for (i = 0; i < table->size; ++i) {
                if (table->ref_count[i] == 0) {
                        table->vlans[i] = vlan;
                        table->ref_count[i] = 1;
                        *index = i;
                        err = 0;
                        goto out;
                }
        }

        err = -ENOSPC;

out:
        mutex_unlock(&table->mutex);
        return err;
}

int register_vlan(struct mlx4_dev *dev, u8 port, u16 vlan, int *index)
{
	int err = -EINVAL;
	int i;
	struct mlx4_vlan_entry *vlan_table;
	int num_vlans;

	mutex_lock(&dev->vlan_table_mutex);
	vlan_table = dev->vlan_table;
	num_vlans = dev->num_vlans;

	for (i = 0; i < num_vlans; i++) {
		if (vlan_table[i].port == port && vlan_table[i].vlan == vlan) {
			/* VLAN already registered, increment reference count */
			vlan_table[i].ref_count++;
			*index = i;
			err = 0;
			goto out;
		}
	}

	/* Check if there is available space */
	for (i = 0; i < num_vlans; i++) {
		if (vlan_table[i].ref_count == 0) {
			vlan_table[i].port = port;
			vlan_table[i].vlan = vlan;
			vlan_table[i].ref_count = 1;
			*index = i;
			err = 0;
			goto out;
		}
	}

	/* No available space */
	err = -ENOSPC;

out:
	mutex_unlock(&dev->vlan_table_mutex);
	return err;
}

int register_vlan(struct mlx4_dev *dev, u8 port, u16 vlan, int *index)
{
	struct mlx4_vlan_table *table = &dev->caps.vlan_table[port];
	int i;

	mutex_lock(&table->mutex);

	for (i = 0; i < MLX4_MAX_VLAN_ENTRIES; ++i) {
		if (table->vlan[i] == vlan) {
			table->ref_count[i]++;
			*index = i;
			mutex_unlock(&table->mutex);
			return 0;
		}
	}

	for (i = 0; i < MLX4_MAX_VLAN_ENTRIES; ++i) {
		if (table->vlan[i] == 0) {
			table->vlan[i] = vlan;
			table->ref_count[i] = 1;
			*index = i;
			mutex_unlock(&table->mutex);
			return 0;
		}
	}

	mutex_unlock(&table->mutex);
	return -ENOSPC;
}

int mlx4_register_vlan(struct mlx4_dev *dev, u8 port, u16 vlan, int *index)
{
	int err = -EINVAL;
	int i;
	struct mlx4_vlan_table *vlan_table;

	if (!dev || !dev->port_vlans || port >= dev->caps.num_ports)
		return -EINVAL;

	vlan_table = &dev->port_vlans[port];
	mutex_lock(&vlan_table->mutex);

	for (i = 0; i < MLX4_MAX_VLAN_ENTRIES; ++i) {
		if (vlan_table->table[i].vlan == vlan) {
			vlan_table->table[i].ref_count++;
			*index = i;
			err = 0;
			goto out;
		}
	}

	for (i = 0; i < MLX4_MAX_VLAN_ENTRIES; ++i) {
		if (vlan_table->table[i].ref_count == 0) {
			vlan_table->table[i].vlan = vlan;
			vlan_table->table[i].ref_count = 1;
			*index = i;
			err = 0;
			break;
		}
	}

out:
	mutex_unlock(&vlan_table->mutex);
	return err;
}

int register_vlan(struct mlx4_dev *dev, u8 port, u16 vlan, int *index)
{
	int err = -EINVAL;
	struct mlx4_vlan_table *vlan_table;
	int i;

	mutex_lock(&dev->port_vlans[port].mutex);
	vlan_table = &dev->port_vlans[port].vlan_table;

	for (i = 0; i < MLX4_VLAN_MAX_ENTRIES; ++i) {
		if (vlan_table->vlan[i] == vlan) {
			/* VLAN already exists, increment ref count */
			vlan_table->ref_count[i]++;
			*index = i;
			err = 0;
			goto out;
		}
	}

	/* Look for a free slot */
	for (i = 0; i < MLX4_VLAN_MAX_ENTRIES; ++i) {
		if (vlan_table->vlan[i] == 0xffff) {
			vlan_table->vlan[i] = vlan;
			vlan_table->ref_count[i] = 1;
			*index = i;
			err = 0;
			break;
		}
	}

out:
	mutex_unlock(&dev->port_vlans[port].mutex);
	return err;
}
